// tb_boed_q16_core.v - Expanded Self-Checking IEEE 1364-2005 / SV-2012 Testbench for boed_q16_core
// Reads N=64 bit-exact golden vectors from golden_vectors.mem spanning 8 diverse physical regimes
// (clean_neg, clean_pos, crowded_doublet, edge_left, edge_right, high_noise, zero_signal, sharp_sat),
// each with 8 sequential multi-step Bayesian updates, generated by rtl_verifier149.py / fpga_boed_dsp.py.
//
// Each 288-bit (72 hex-char) line in golden_vectors.mem packs:
//   [287:256] f_init_hz              (signed 32-bit Hz)
//   [255:224] f_probe_hz             (signed 32-bit Hz)
//   [223:192] y_meas_q16             (signed Q16.16)
//   [191:160] inv_gamma_q24          (unsigned Q24)
//   [159:128] inv_2var_q16           (signed Q16.16)
//   [127:112] delta_fisher_q4        (unsigned Q4)
//   [111:96]  max_off_q4             (unsigned Q4)
//   [95:88]   step_idx               (unsigned 8-bit)
//   [87:80]   reset_prior_flag       (1 = reload Gaussian prior before step)
//   [79:64]   exp_std_q4             (expected unsigned Q4 std)
//   [63:32]   exp_mu_off_q8          (expected signed Q8 mu offset)
//   [31:0]    exp_next_probe_off_q8  (expected signed Q8 next Fisher probe offset)
//
// Also directly verifies:
//   - Stage-0 SPRT 4-cycle pipelined fast-abort engine (donor-present & blank-site streams + reset)
//   - Standalone boed_isqrt_cordic 16-stage restoring pipeline on 13 boundary/edge-case 32-bit inputs
//
// Run with Icarus Verilog:
//   iverilog -g2012 -Wall -o sim_boed boed_lut_rom.v boed_isqrt_cordic.v boed_q16_core.v tb_boed_q16_core.v
//   vvp sim_boed
`timescale 1ns/1ps

module tb_boed_q16_core;
    localparam integer N_VECTORS = 64;
    localparam integer N_BINS    = 1001;

    reg                clk;
    reg                rst_n;

    reg                sprt_start;
    reg                sprt_reset_llr;
    reg  signed [31:0] sprt_y_q16;
    reg  signed [31:0] sprt_half_sig_q16;
    reg  signed [31:0] sprt_scale_q16;
    reg  signed [31:0] sprt_thresh_q16;
    wire               sprt_done;
    wire               sprt_decision_valid;
    wire               sprt_donor_present;
    wire signed [31:0] sprt_llr_q16;

    reg                step_start;
    reg                prior_load_en;
    reg         [9:0]  prior_load_addr;
    reg  signed [31:0] prior_load_lp_q16;
    reg  signed [31:0] f_init_hz;
    reg  signed [31:0] f_probe_hz;
    reg  signed [31:0] y_meas_q16;
    reg         [31:0] inv_gamma_q24;
    reg  signed [31:0] inv_2var_q16;
    reg         [15:0] delta_fisher_q4;
    reg         [15:0] max_off_q4;
    reg         [7:0]  step_idx;

    wire               busy;
    wire               step_done;
    wire signed [31:0] mu_off_q8;
    wire        [15:0] std_q4;
    wire signed [31:0] next_probe_off_q8;
    wire        [15:0] cycle_count;

    // Standalone isqrt DUT for boundary verification
    reg                sq_in_v;
    reg         [31:0] sq_rad;
    wire               sq_out_v;
    wire        [15:0] sq_root;

    // 250 MHz clock (4.0 ns period)
    initial clk = 1'b0;
    always #2 clk = ~clk;

    boed_q16_core dut (
        .clk                (clk),
        .rst_n              (rst_n),
        .sprt_start         (sprt_start),
        .sprt_reset_llr     (sprt_reset_llr),
        .sprt_y_q16         (sprt_y_q16),
        .sprt_half_sig_q16  (sprt_half_sig_q16),
        .sprt_scale_q16     (sprt_scale_q16),
        .sprt_thresh_q16    (sprt_thresh_q16),
        .sprt_done          (sprt_done),
        .sprt_decision_valid(sprt_decision_valid),
        .sprt_donor_present (sprt_donor_present),
        .sprt_llr_q16       (sprt_llr_q16),
        .step_start         (step_start),
        .prior_load_en      (prior_load_en),
        .prior_load_addr    (prior_load_addr),
        .prior_load_lp_q16  (prior_load_lp_q16),
        .f_init_hz          (f_init_hz),
        .f_probe_hz         (f_probe_hz),
        .y_meas_q16         (y_meas_q16),
        .inv_gamma_q24      (inv_gamma_q24),
        .inv_2var_q16       (inv_2var_q16),
        .delta_fisher_q4    (delta_fisher_q4),
        .max_off_q4         (max_off_q4),
        .step_idx           (step_idx),
        .busy               (busy),
        .step_done          (step_done),
        .mu_off_q8          (mu_off_q8),
        .std_q4             (std_q4),
        .next_probe_off_q8  (next_probe_off_q8),
        .cycle_count        (cycle_count)
    );

    boed_isqrt_cordic u_isqrt_tb (
        .clk      (clk),
        .rst_n    (rst_n),
        .in_valid (sq_in_v),
        .radicand (sq_rad),
        .out_valid(sq_out_v),
        .root     (sq_root)
    );

    reg [287:0] vec_mem [0:N_VECTORS-1];
    integer i, b, cyc;
    integer boed_errors, sprt_errors, isqrt_errors;
    integer max_mu_err, max_std_err, max_next_err;
    integer cur_mu_err, cur_std_err, cur_next_err;
    integer min_cyc, max_cyc;

    reg [15:0]        exp_std;
    reg signed [31:0] exp_mu;
    reg signed [31:0] exp_next;
    reg [7:0]         reset_flag;
    integer           df_hz;

    // SPRT reference variables
    reg signed [31:0] sprt_ref_llr;
    reg signed [63:0] sprt_ref_prod;
    reg signed [31:0] sprt_ref_delta;
    reg signed [31:0] sprt_shots [0:7];
    integer           s, sprt_lat, sprt_max_err, cur_sprt_err;

    // isqrt corner-case vectors
    reg [31:0] sq_test_in  [0:12];
    reg [15:0] sq_test_exp [0:12];
    integer    sq_lat;

    initial begin
        $readmemh("golden_vectors.mem", vec_mem);

        rst_n             = 1'b0;
        sprt_start        = 1'b0;
        sprt_reset_llr    = 1'b0;
        sprt_y_q16        = 32'sd0;
        sprt_half_sig_q16 = 32'sd0;
        sprt_scale_q16    = 32'sd0;
        sprt_thresh_q16   = 32'sd0;
        step_start        = 1'b0;
        prior_load_en     = 1'b0;
        prior_load_addr   = 10'd0;
        prior_load_lp_q16 = 32'sd0;
        f_init_hz         = 32'sd0;
        f_probe_hz        = 32'sd0;
        y_meas_q16        = 32'sd0;
        inv_gamma_q24     = 32'd0;
        inv_2var_q16      = 32'sd0;
        delta_fisher_q4   = 16'd0;
        max_off_q4        = 16'd0;
        step_idx          = 8'd0;
        sq_in_v           = 1'b0;
        sq_rad            = 32'd0;

        boed_errors       = 0;
        sprt_errors       = 0;
        isqrt_errors      = 0;
        max_mu_err        = 0;
        max_std_err       = 0;
        max_next_err      = 0;
        sprt_max_err      = 0;
        min_cyc           = 999999;
        max_cyc           = 0;

        // Drive all stimulus cleanly on negedge clk to eliminate setup/hold delta races
        repeat (4) @(negedge clk);
        rst_n = 1'b1;
        @(negedge clk);

        // -------------------------------------------------------------------
        // Test Suite 1: 64 Diverse Golden BOED Vectors (8 regimes x 8 steps)
        // -------------------------------------------------------------------
        for (i = 0; i < N_VECTORS; i = i + 1) begin
            f_init_hz       = vec_mem[i][287:256];
            f_probe_hz      = vec_mem[i][255:224];
            y_meas_q16      = vec_mem[i][223:192];
            inv_gamma_q24   = vec_mem[i][191:160];
            inv_2var_q16    = vec_mem[i][159:128];
            delta_fisher_q4 = vec_mem[i][127:112];
            max_off_q4      = vec_mem[i][111:96];
            step_idx        = vec_mem[i][95:88];
            reset_flag      = vec_mem[i][87:80];
            exp_std         = vec_mem[i][79:64];
            exp_mu          = vec_mem[i][63:32];
            exp_next        = vec_mem[i][31:0];

            // Reload Gaussian prior sigma=2000 Hz when starting a new trajectory:
            // Exact 32-bit-safe integer identity: -((df_bin^2 * 1024 + 625) / 1250)
            if (reset_flag != 8'd0) begin
                for (b = 0; b < N_BINS; b = b + 1) begin
                    df_hz             = b - 500;
                    prior_load_en     = 1'b1;
                    prior_load_addr   = b[9:0];
                    prior_load_lp_q16 = -(((df_hz * df_hz * 32'sd1024) + 32'sd625) / 32'sd1250);
                    @(negedge clk);
                end
                prior_load_en = 1'b0;
                @(negedge clk);
            end

            step_start = 1'b1;
            @(negedge clk);
            step_start = 1'b0;

            cyc = 0;
            while (!step_done && cyc < 700) begin
                @(negedge clk);
                cyc = cyc + 1;
            end

            if (!step_done) begin
                $display("FAIL_TIMEOUT vec=%0d", i);
                boed_errors = boed_errors + 1;
            end else begin
                if (cycle_count < min_cyc) min_cyc = cycle_count;
                if (cycle_count > max_cyc) max_cyc = cycle_count;

                if (cycle_count !== 16'd584) begin
                    $display("FAIL_CYC vec=%0d got=%0d exp=584", i, cycle_count);
                    boed_errors = boed_errors + 1;
                end

                cur_mu_err   = (mu_off_q8 >= exp_mu) ? (mu_off_q8 - exp_mu) : (exp_mu - mu_off_q8);
                cur_std_err  = (std_q4 >= exp_std) ? (std_q4 - exp_std) : (exp_std - std_q4);
                cur_next_err = (next_probe_off_q8 >= exp_next) ?
                               (next_probe_off_q8 - exp_next) : (exp_next - next_probe_off_q8);

                if (cur_mu_err   > max_mu_err)   max_mu_err   = cur_mu_err;
                if (cur_std_err  > max_std_err)  max_std_err  = cur_std_err;
                if (cur_next_err > max_next_err) max_next_err = cur_next_err;

                if (mu_off_q8 !== exp_mu || std_q4 !== exp_std || next_probe_off_q8 !== exp_next) begin
                    $display("FAIL_VEC vec=%0d mu=%0d(exp=%0d) std=%0d(exp=%0d) next=%0d(exp=%0d) cyc=%0d",
                             i, mu_off_q8, exp_mu, std_q4, exp_std, next_probe_off_q8, exp_next, cycle_count);
                    boed_errors = boed_errors + 1;
                end
            end
            @(negedge clk);
        end

        // -------------------------------------------------------------------
        // Test Suite 2: Stage-0 SPRT 4-Cycle Pipeline (Donor Present & Blank)
        // -------------------------------------------------------------------
        sprt_half_sig_q16 = 32'sd13107;    // 0.20 in Q16.16 (0.5 * 0.40)
        sprt_scale_q16    = 32'sd1820444;  // 0.40 / 0.12^2 = 27.7778 in Q16.16
        sprt_thresh_q16   = 32'sd301466;   // 4.60 in Q16.16

        // 4 donor-present shots followed by reset and 4 blank-site shots
        sprt_shots[0] = 32'sd27525;  // +0.42
        sprt_shots[1] = 32'sd24904;  // +0.38
        sprt_shots[2] = 32'sd29491;  // +0.45
        sprt_shots[3] = 32'sd26214;  // +0.40
        sprt_shots[4] = -32'sd3277;  // -0.05
        sprt_shots[5] = 32'sd1966;   // +0.03
        sprt_shots[6] = -32'sd1311;  // -0.02
        sprt_shots[7] = 32'sd655;    // +0.01

        sprt_ref_llr = 32'sd0;
        for (s = 0; s < 8; s = s + 1) begin
            if (s == 4) begin
                sprt_reset_llr = 1'b1;
                @(negedge clk);
                sprt_reset_llr = 1'b0;
                sprt_ref_llr   = 32'sd0;
                @(negedge clk);
            end

            sprt_y_q16 = sprt_shots[s];
            sprt_start = 1'b1;
            @(negedge clk);
            sprt_start = 1'b0;

            // Count exact latency cycles until sprt_done asserts (expect 4 total cycles)
            sprt_lat = 1;
            while (!sprt_done && sprt_lat < 16) begin
                @(negedge clk);
                sprt_lat = sprt_lat + 1;
            end

            sprt_ref_prod  = ({{32{sprt_shots[s][31]}}, sprt_shots[s]} -
                              {{32{sprt_half_sig_q16[31]}}, sprt_half_sig_q16}) *
                             {{32{sprt_scale_q16[31]}}, sprt_scale_q16};
            sprt_ref_delta = (sprt_ref_prod + 64'sd32768) >>> 16;
            sprt_ref_llr   = sprt_ref_llr + sprt_ref_delta;

            cur_sprt_err = (sprt_llr_q16 >= sprt_ref_llr) ?
                           (sprt_llr_q16 - sprt_ref_llr) : (sprt_ref_llr - sprt_llr_q16);
            if (cur_sprt_err > sprt_max_err) sprt_max_err = cur_sprt_err;

            if (sprt_lat !== 4 || sprt_llr_q16 !== sprt_ref_llr) begin
                $display("FAIL_SPRT shot=%0d lat=%0d(exp=4) llr=%0d(exp=%0d)",
                         s, sprt_lat, sprt_llr_q16, sprt_ref_llr);
                sprt_errors = sprt_errors + 1;
            end
            if (s == 3 && (!sprt_decision_valid || !sprt_donor_present)) begin
                $display("FAIL_SPRT_DEC donor_present expected valid=1 donor=1 got=%0d/%0d",
                         sprt_decision_valid, sprt_donor_present);
                sprt_errors = sprt_errors + 1;
            end
            if (s == 7 && (!sprt_decision_valid || sprt_donor_present)) begin
                $display("FAIL_SPRT_DEC blank_site expected valid=1 donor=0 got=%0d/%0d",
                         sprt_decision_valid, sprt_donor_present);
                sprt_errors = sprt_errors + 1;
            end
            @(negedge clk);
        end

        // -------------------------------------------------------------------
        // Test Suite 3: Standalone 16-Stage Restoring boed_isqrt_cordic Edges
        // -------------------------------------------------------------------
        sq_test_in[0]  = 32'd0;          sq_test_exp[0]  = 16'd0;
        sq_test_in[1]  = 32'd1;          sq_test_exp[1]  = 16'd1;
        sq_test_in[2]  = 32'd2;          sq_test_exp[2]  = 16'd1;
        sq_test_in[3]  = 32'd3;          sq_test_exp[3]  = 16'd1;
        sq_test_in[4]  = 32'd4;          sq_test_exp[4]  = 16'd2;
        sq_test_in[5]  = 32'd15;         sq_test_exp[5]  = 16'd3;
        sq_test_in[6]  = 32'd16;         sq_test_exp[6]  = 16'd4;
        sq_test_in[7]  = 32'd255;        sq_test_exp[7]  = 16'd15;
        sq_test_in[8]  = 32'd256;        sq_test_exp[8]  = 16'd16;
        sq_test_in[9]  = 32'd65535;      sq_test_exp[9]  = 16'd255;
        sq_test_in[10] = 32'd65536;      sq_test_exp[10] = 16'd256;
        sq_test_in[11] = 32'hFFFFFFFE;   sq_test_exp[11] = 16'd65535;
        sq_test_in[12] = 32'hFFFFFFFF;   sq_test_exp[12] = 16'd65535;

        for (s = 0; s < 13; s = s + 1) begin
            sq_rad  = sq_test_in[s];
            sq_in_v = 1'b1;
            @(negedge clk);
            sq_in_v = 1'b0;

            sq_lat = 1;
            while (!sq_out_v && sq_lat < 32) begin
                @(negedge clk);
                sq_lat = sq_lat + 1;
            end
            if (sq_lat !== 16 || sq_root !== sq_test_exp[s]) begin
                $display("FAIL_ISQRT idx=%0d in=%0d got=%0d(exp=%0d) lat=%0d(exp=16)",
                         s, sq_test_in[s], sq_root, sq_test_exp[s], sq_lat);
                isqrt_errors = isqrt_errors + 1;
            end
            @(negedge clk);
        end

        $display("SUMMARY vectors=%0d boed_errors=%0d sprt_errors=%0d isqrt_errors=%0d max_mu_err=%0d max_std_err=%0d max_next_err=%0d sprt_max_err=%0d min_cyc=%0d max_cyc=%0d",
                 N_VECTORS, boed_errors, sprt_errors, isqrt_errors,
                 max_mu_err, max_std_err, max_next_err, sprt_max_err, min_cyc, max_cyc);

        if (boed_errors == 0 && sprt_errors == 0 && isqrt_errors == 0) begin
            $display("PASS: All %0d diverse golden vectors + 8 SPRT shots + 13 isqrt corners verified at 0 LSB / 584 cycles!", N_VECTORS);
        end else begin
            $display("FAIL: boed_errors=%0d sprt_errors=%0d isqrt_errors=%0d", boed_errors, sprt_errors, isqrt_errors);
            $fatal(1);
        end
        $finish;
    end
endmodule
